parameters.jsCode:
// Pull original lead + campaign data directly from Split Targets node
const original = $('Split Targets').item.json;
const lead = original.targets ?? original;

// Get website content from this branch (Extract Text node's output)
let rawText = $json.body_text ?? "";
if (Array.isArray(rawText)) {
  rawText = rawText.join(" ");
}
if (typeof rawText !== "string") {
  rawText = JSON.stringify(rawText);
}

let cleanedText = rawText
  .replace(/\s+/g, " ")
  .replace(/\[https?:\/\/[^\]]*\]/g, "")
  .trim();

const MAX_CHARS = 3000;
if (cleanedText.length > MAX_CHARS) {
  cleanedText = cleanedText.substring(0, MAX_CHARS) + "...";
}

return {
  company_name: lead.company_name,
  website: lead.website,
  expected_test_category: lead.expected_test_category,
  campaign: original.campaign,
  website_text: cleanedText
};

